// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public { c = new PENNY_BY_PENNY(); }

    function testFuzz_property(uint256 v1, uint256 v2, address actor) public {
        vm.assume(actor != address(0));
        // set MinSum before initialization to a fuzzed value
        c.SetMinSum(v1);
        // initialize: from now on SetMinSum must be permanently disabled
        vm.prank(actor);
        c.Initialized();
        // a later SetMinSum must not change MinSum (it reverts in the reference)
        vm.prank(actor);
        try c.SetMinSum(v2) { /* mutant path */ } catch { /* reference path */ }
        assertTrue(c.MinSum() == v1);
    }
}
